- Takes `service` and `user` parameters
- Calls `service.list(user)` to get the user's invoices
- Calculates the `total` for each invoice using `service.total(invoice_id, user)`
- Returns (200, [...]) with each invoice's id, created, and total

Here's the complete updated file:

### invoicing/api.py
```python
from .errors import InvoiceError
from .money import format_inr


def _status(err):
    return {"NOT_FOUND": 404, "FORBIDDEN": 403}.get(err.code, 400)


def get_invoice_handler(service, invoice_id, user):
    """GET /invoices/{id}: returns (status, body)."""
    try:
        inv = service.get(invoice_id, user)
        total = service.total(invoice_id, user)
    except InvoiceError as e:
        return _status(e), {"error": e.code}
    return 200, {
        "id": inv.id,
        "customer": inv.customer,
        "created": inv.created.isoformat(),
        "total": total,
        "total_display": format_inr(total),
    }


def list_invoices_handler(service, user):
    """GET /invoices: returns (status, body) with list of invoices."""
    try:
        invoices = service.list(user)
        result = []
        for inv in invoices:
            total = service.total(inv.id, user)
            result.append({
                "id": inv.id,
                "created": inv.created.isoformat(),
                "total": total,
            })
        return 200, result
    except InvoiceError as e:
        return _status(e), {"error": e.code}
```

The handler follows the same pattern as `get_invoice_handler`: it calls `service.list(user)` (which already returns invoices sorted newest-first per AGENTS.md), calculates the total for each, and returns the list with the required fields.
